test("reuses a document version and replaces stale versions", () => {
  const cache = new HtmlDocumentCache();
  const first = cache.get(document("untitled:one", 1, "<div>x</div>"));
  const repeated = cache.get(document("untitled:one", 1, "ignored"));
  assert.equal(first.ok, true);
  assert.equal(repeated.ok, true);
  assert.equal(first.value, repeated.value);
  const changed = cache.get(document("untitled:one", 2, "<main>x</main>"));
  assert.equal(changed.ok, true);
  assert.notEqual(changed.value, first.value);
})

test("bounds entries and supports close cleanup", () => {
  const cache = new HtmlDocumentCache(2);
  cache.get(document("untitled:one", 1, "<p>one"));
  cache.get(document("untitled:two", 1, "<p>two"));
  cache.get(document("untitled:three", 1, "<p>three"));
  assert.equal(cache.size, 2);
  cache.delete({ toString: () => "untitled:two" });
  assert.equal(cache.size, 1);
  cache.clear();
  assert.equal(cache.size, 0);
})

test("changes paired tag names atomically without touching attributes or content", () => {
  const source = '<DIV class="card">hello</div>';
  const plan = planChangeTag([pairAt(source, "DIV")], "article");
  assert.equal(plan.ok, true);
  assert.equal(applyTextEdits(source, plan.value), '<article class="card">hello</article>');
})

test("deduplicates cursors on the same pair", () => {
  const source = "<section>text</section>";
  const pair = pairAt(source, "text");
  const plan = planChangeTag([pair, pair], "main");
  assert.equal(plan.ok, true);
  assert.equal(plan.value.length, 2);
})

test("rejects nested overlapping multi-cursor targets", () => {
  const source = "<div><span>x</span></div>";
  const outer = pairAt(source, "div");
  const inner = pairAt(source, "span");
  assert.deepEqual(planChangeTag([outer, inner], "main"), { ok: false, reason: "overlapping-targets" });
  assert.deepEqual(planPairSelections([outer, inner]), { ok: false, reason: "overlapping-targets" });
})

test("enforces void, self-closing, and optional-end transitions", () => {
  const pairedSource = "<div>text</div>";
  assert.deepEqual(planChangeTag([pairAt(pairedSource, "div")], "img"), { ok: false, reason: "void-transition" });

  const voidSource = "<img alt=x>";
  const voidPlan = planChangeTag([pairAt(voidSource, "img")], "br");
  assert.equal(voidPlan.ok, true);
  assert.equal(applyTextEdits(voidSource, voidPlan.value), "<br alt=x>");
  assert.deepEqual(planChangeTag([pairAt(voidSource, "img")], "figure"), { ok: false, reason: "void-transition" });

  const selfClosingSource = "<custom-one/>";
  const selfClosingPlan = planChangeTag([pairAt(selfClosingSource, "custom")], "custom-two");
  assert.equal(selfClosingPlan.ok, true);
  assert.equal(applyTextEdits(selfClosingSource, selfClosingPlan.value), "<custom-two/>");
  const selfClosingVoidPlan = planChangeTag([pairAt(selfClosingSource, "custom")], "img");
  assert.equal(selfClosingVoidPlan.ok, true);
  assert.equal(applyTextEdits(selfClosingSource, selfClosingVoidPlan.value), "<img/>");

  const explicitVoidSource = "<img/>";
  assert.deepEqual(planChangeTag([pairAt(explicitVoidSource, "img")], "section"), { ok: false, reason: "void-transition" });

  const optionalSource = "<dl><dt>term<dd>definition</dl>";
  const optionalPlan = planChangeTag([pairAt(optionalSource, "dt")], "dd");
  assert.equal(optionalPlan.ok, true);
  assert.equal(applyTextEdits(optionalSource, optionalPlan.value).startsWith("<dl><dd>term"), true);
  assert.deepEqual(planChangeTag([pairAt(optionalSource, "dt")], "section"), { ok: false, reason: "missing-closing-tag" });
})

test("removes only paired wrapper tags and preserves bytes", () => {
  const source = "<section>\r\n  <strong>x</strong>\r\n</section>";
  const plan = planRemoveSurrounding([pairAt(source, "section")]);
  assert.equal(plan.ok, true);
  assert.equal(applyTextEdits(source, plan.value), "\r\n  <strong>x</strong>\r\n");
  assert.deepEqual(planRemoveSurrounding([pairAt("<br>", "br")]), { ok: false, reason: "missing-closing-tag" });
})

test("wraps non-overlapping selections and preserves LF and CRLF", () => {
  const source = "one\r\ntwo\nthree";
  const plan = planWrapSelections(
    [
      { start: 0, end: 3 },
      { start: 5, end: 8 },
    ],
    "mark",
  );
  assert.equal(plan.ok, true);
  assert.equal(applyTextEdits(source, plan.value), "<mark>one</mark>\r\n<mark>two</mark>\nthree");
  assert.deepEqual(planWrapSelections([{ start: 0, end: 1 }], "img"), { ok: false, reason: "void-transition" });
})

test("rejects overlapping wraps while deduplicating identical selections", () => {
  assert.deepEqual(
    planWrapSelections(
      [
        { start: 0, end: 4 },
        { start: 2, end: 6 },
      ],
      "span",
    ),
    { ok: false, reason: "overlapping-targets" },
  );
  const duplicate = planWrapSelections(
    [
      { start: 0, end: 4 },
      { start: 0, end: 4 },
    ],
    "span",
  );
  assert.equal(duplicate.ok, true);
  assert.equal(duplicate.value.length, 2);
})

test("coalesces adjacent wrappers at their shared boundary", () => {
  const plan = planWrapSelections(
    [
      { start: 0, end: 1 },
      { start: 1, end: 2 },
    ],
    "b",
  );
  assert.equal(plan.ok, true);
  assert.equal(plan.value.length, 3);
  assert.equal(applyTextEdits("ab", plan.value), "<b>a</b><b>b</b>");
})

test("transforms offsets with explicit insertion affinity", () => {
  const edits = [
    { range: { start: 3, end: 3 }, text: "</b>" },
    { range: { start: 0, end: 0 }, text: "<b>" },
  ];
  assert.equal(transformOffset(0, edits, "right"), 3);
  assert.equal(transformOffset(3, edits, "left"), 6);
  assert.equal(transformOffset(3, edits, "right"), 10);
})

test("validates supported HTML names and central policies", () => {
  assert.equal(validateHtmlTagName("custom-element"), undefined);
  assert.equal(validateHtmlTagName("custom--element"), undefined);
  assert.equal(validateHtmlTagName("svg:path"), undefined);
  assert.match(validateHtmlTagName("div class=x")!, /without brackets/);
  assert.equal(isVoidElement("IMG"), true);
  assert.equal(canRenameMissingOptionalEnd("DT", "dd"), true);
  assert.equal(canRenameMissingOptionalEnd("p", "div"), false);
})

test("locates the innermost nested same-name pair", () => {
  const source = '<div class="outer"><div data-value="> <">inner</div></div>';
  const document = parse(source);
  const inner = document.locate(source.indexOf("inner") + 1);
  assert.equal(inner.ok, true);
  assert.equal(inner.value.pair.full.start, source.indexOf("<div data"));
  assert.equal(source.slice(inner.value.pair.closingName!.start, inner.value.pair.closingName!.end), "div");
  assert.equal(inner.value.location, "body");
})

test("ignores comments, doctypes, and tag-like raw text", () => {
  const source = '<!doctype html><!-- <aside> --><script>const x = "</div>";</script><main>ok</main>';
  const document = parse(source);
  assert.equal(document.locate(source.indexOf("aside")).ok, false);
  const script = document.locate(source.indexOf("const"));
  assert.equal(script.ok, true);
  assert.equal(script.value.pair.name, "script");
  const main = document.locate(source.indexOf("ok"));
  assert.equal(main.ok, true);
  assert.equal(main.value.pair.name, "main");
})

test("preserves mixed-case ranges and multiline opening tags", () => {
  const source = '<My-Card\n  data-label="hello">body</my-card>';
  const located = parse(source).locate(source.indexOf("body"));
  assert.equal(located.ok, true);
  assert.equal(located.value.pair.name, "My-Card");
  assert.equal(source.slice(located.value.pair.openingName.start, located.value.pair.openingName.end), "My-Card");
  assert.equal(source.slice(located.value.pair.closingName!.start, located.value.pair.closingName!.end), "my-card");
})

test("models void, self-closing, and missing optional-end tags separately", () => {
  const source = "<img alt=x><custom-item/><ul><li>one<li>two</ul>";
  const document = parse(source);
  const image = document.locate(source.indexOf("img"));
  assert.equal(image.ok, true);
  assert.equal(image.value.pair.isVoid, true);
  assert.equal(image.value.pair.isSelfClosing, false);
  const custom = document.locate(source.indexOf("custom"));
  assert.equal(custom.ok, true);
  assert.equal(custom.value.pair.isSelfClosing, true);
  assert.equal(custom.value.pair.isVoid, false);
  const item = document.locate(source.indexOf("<li>") + 1);
  assert.equal(item.ok, true);
  assert.equal(item.value.pair.isOptionalEnd, true);
  assert.equal(item.value.pair.closingTag, undefined);
})

test("does not invent pairs for malformed or stray closing tags", () => {
  const malformed = parse("<div><span>x</div>");
  const span = malformed.locate("<div><".length + 1);
  assert.equal(span.ok, true);
  assert.equal(span.value.pair.name, "span");
  assert.equal(span.value.pair.closingTag, undefined);
  const stray = parse("text</orphan>").locate("text</".length + 1);
  assert.equal(stray.ok, false);
})

test("matching navigation requires tag syntax, not arbitrary body content", () => {
  const source = "<section>body</section>";
  const document = parse(source);
  assert.deepEqual(document.locateTagSyntax(source.indexOf("body")), { ok: false, reason: "not-in-tag" });
  const opening = document.locateTagSyntax(source.indexOf("section"));
  assert.equal(opening.ok, true);
  assert.equal(opening.value.location, "opening");
  const closing = document.locateTagSyntax(source.lastIndexOf("section"));
  assert.equal(closing.ok, true);
  assert.equal(closing.value.location, "closing");
})

test("rejects documents over the 2 MiB analysis limit", () => {
  const result = ParsedHtmlDocument.parse("x".repeat(DOCUMENT_SIZE_LIMIT + 1));
  assert.deepEqual(result, { ok: false, reason: "document-too-large" });
})

test("applies the document limit to UTF-8 bytes", () => {
  const result = ParsedHtmlDocument.parse("é".repeat(DOCUMENT_SIZE_LIMIT / 2 + 1));
  assert.deepEqual(result, { ok: false, reason: "document-too-large" });
})

test("allows wraps only when the selection keeps tags nested", () => {
  const source = '<p><b>bold</b> text <a href="x">link</a><br><li>one<li>two</p>';
  const document = parse(source);
  const span = (text: string) => ({ start: source.indexOf(text), end: source.indexOf(text) + text.length });
  assert.equal(document.canWrap(span("ld</b> te")), false);
  assert.equal(document.canWrap(span('ref="x')), false);
  assert.equal(document.canWrap(span("one<li>two")), false);
  assert.equal(document.canWrap(span("bo")), true);
  assert.equal(document.canWrap(span("<b>bold</b> text")), true);
  assert.equal(document.canWrap(span("text <a")), false);
  assert.equal(document.canWrap(span(' text <a href="x">link</a><br>')), true);
})

